package com.bank.merge;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class MergeKListsDemo {

    private static final Logger log = Logger.getLogger(MergeKListsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        LedgerMerger merger = new LedgerMerger();

        List<List<BigDecimal>> branches = List.of(
                List.of(new BigDecimal("100"), new BigDecimal("500"), new BigDecimal("900")),
                List.of(new BigDecimal("200"), new BigDecimal("400")),
                List.of(new BigDecimal("50"), new BigDecimal("600"), new BigDecimal("1000"))
        );

        List<BigDecimal> merged = merger.merge(branches);
        log.info(() -> "Merged sorted ledger: " + merged);
    }
}

