class LedgerMerger {

    private static final Logger log = Logger.getLogger(LedgerMerger.class.getName());

    // A heap entry tracks which list and position an element came from.
    private static final class Entry {
        final BigDecimal value; final int list; final int pos;
        Entry(BigDecimal value, int list, int pos) { this.value = value; this.list = list; this.pos = pos; }
    }

    java.util.List<BigDecimal> merge(java.util.List<java.util.List<BigDecimal>> lists) {
        java.util.PriorityQueue<Entry> heap =
                new java.util.PriorityQueue<>(java.util.Comparator.comparing(e -> e.value));

        // Seed with the first element of each non-empty list.
        for (int i = 0; i < lists.size(); i++) {
            if (!lists.get(i).isEmpty()) {
                heap.offer(new Entry(lists.get(i).get(0), i, 0));
            }
        }

        java.util.List<BigDecimal> result = new java.util.ArrayList<>();
        while (!heap.isEmpty()) {
            Entry smallest = heap.poll();
            result.add(smallest.value);
            int nextPos = smallest.pos + 1;
            if (nextPos < lists.get(smallest.list).size()) {
                heap.offer(new Entry(lists.get(smallest.list).get(nextPos), smallest.list, nextPos));
            }
            log.fine(() -> "  took " + smallest.value + " from list " + smallest.list);
        }
        return result;
    }
}

